insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('1d56b8be-95f9-4875-8bc0-14d3480d6311', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$inleiding: vaccinatie tegen pneumokokkenziekte$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context1.png$$,
   $$Sinds 2020 krijgen mensen die ouder zijn dan zestig jaar een uitnodiging voor een vaccinatie tegen pneumokokkenziekte. Mevrouw Hertogs komt naar het vaccinatiespreekuur, waar doktersassistente Vicky de prikken zet.$$, 'inline'),
  ('22ccc262-f606-4708-b599-c935c94865d7', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$kader: de pneumokokbacterie (foto)$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context2.png$$,
   $$Pneumokokkenziekte wordt veroorzaakt door de pneumokokbacterie (Streptococcus pneumoniae, zie afbeelding). Veel kinderen en volwassenen hebben pneumokokbacteriën in het slijmvlies van hun neusholte. Zolang mensen gezond zijn, hebben ze geen voordeel of nadeel van deze bacteriën. Ze kunnen de bacteriën wel verspreiden door hoesten of niezen.
Bij ouderen met een verminderde afweer kan de pneumokokbacterie de dekweefselcellen van de luchtwegen passeren. De bacterie komt dan in het inwendig milieu terecht, waar die een ernstige longontsteking kan veroorzaken.
afbeelding: microscopische foto van pneumokokbacteriën (schaalstreep 1 µm)$$, 'inline'),
  ('4987535c-db77-4dc7-9735-ba2bed8617e9', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$fysische en (bio)chemische barrière in de neusholte$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context3.png$$,
   $$In de neusholte bevinden zich een fysische en een (bio)chemische barrière van de aangeboren afweer tegen het binnendringen van de pneumokokbacterie.$$, 'inline'),
  ('c6f929d4-9764-4b66-af06-830d1bceb9f6', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$symbiose in het neusslijmvlies en het inwendig milieu$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context4.png$$,
   $$Tussen de mens en de pneumokokbacterie is sprake van symbiose. In het neusslijmvlies is de symbiose anders dan in het inwendig milieu.$$, 'inline'),
  ('6bf90a3e-943c-44da-b972-093e313a4a2d', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$virusinfectie vergroot de kans op binnendringen$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context5.png$$,
   $$Vicky vertelt aan mevrouw Hertogs dat bij gezonde mensen de kans klein is dat de pneumokokbacterie het inwendig milieu bereikt. Bij iemand die een virusinfectie heeft in de luchtwegen is die kans groter.$$, 'inline'),
  ('c07219c1-53cf-416b-b971-3a12aff49000', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$formule voor de diffusiesnelheid van zuurstof; longontsteking$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context6.png$$,
   $$De diffusiesnelheid V van zuurstof vanuit de longblaasjes naar het bloed, kan worden bepaald met de volgende formule:
V = D × A × (c₂ − c₁) / x
− D is de diffusieconstante.
− A is de oppervlakte van de longblaasjes.
− (c₂ − c₁) is het verschil in zuurstofconcentratie tussen bloed en lucht in de longblaasjes.
− x is de diffusieafstand.
In het inwendig milieu van de longen kunnen pneumokokbacteriën een longontsteking veroorzaken. Bij een longontsteking komt er meer vocht met witte bloedcellen in de longblaasjes. Hierdoor verandert de diffusiesnelheid van zuurstof vanuit de longblaasjes naar de longhaarvaten.
Een factor in de formule wordt groter.$$, 'inline'),
  ('2a23fc57-3d83-46b9-933b-b45cad153675', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$hyperventileren door activiteit van het ademcentrum$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context7.png$$,
   $$Wanneer mevrouw Hertogs de naald ziet, raakt ze gestrest. Ze gaat hyperventileren: door activiteit van haar ademcentrum neemt haar ademhalingsfrequentie toe.$$, 'inline'),
  ('4e4e3a7b-418f-42e1-9535-9f7fcd54175c', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$kader: app tegen prikangst die stressreacties monitort$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context8.png$$,
   $$Voor mensen met prikangst heeft Vicky een speciale app op haar smartphone. Ze laat mevrouw Hertogs via deze app een spelletje spelen. In het spelletje krijgt mevrouw Hertogs opdrachten die ervoor zorgen dat ze meer ontspant. Hierdoor stopt het hyperventileren.
Tijdens het spelen monitort de app stressreacties in het gezicht, zoals transpiratie, pupilgrootte, het bleek of rood worden van de huid en de hartslagfrequentie.
foto: doktersassistente bij een oudere vrouw$$, 'inline'),
  ('bae9381c-65dd-45b6-bdeb-a7e7ce031f0e', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$drie uitspraken over stressreacties$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context9.png$$,
   $$Hieronder staan uitspraken over stressreacties.
1 De pupil wordt groter onder invloed van het orthosympathisch deel van het autonoom zenuwstelsel.
2 Door transpiratie neemt de lichaamstemperatuur toe.
3 Adrenaline stimuleert de hartslagfrequentie.$$, 'inline'),
  ('f7fd0693-fcd9-4ea8-99d0-4a1f5e8e4c60', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$bleek worden door samentrekken van spiertjes van bloedvaten$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context10.png$$,
   $$Het bleek worden is het gevolg van het samentrekken van spiertjes van bepaalde bloedvaten in het gezicht.$$, 'inline'),
  ('96b736d8-0869-4869-a900-15ea45f866a2', 'aea52887-ba8e-42f3-ab63-712a17759d93', $$het vaccin beschermt een aantal jaren$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-context11.png$$,
   $$Wanneer mevrouw Hertogs ontspannen is, kan Vicky haar vaccineren. Het vaccin biedt een aantal jaren bescherming tegen de pneumokokkenziekte.$$, 'inline'),
  ('ff7fa309-1e2f-4151-befd-a2cb92c6e35d', 'f9444b72-3021-4f43-b449-593c3fe00314', $$inleiding: kajakken in Lac Cai op Bonaire$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context1.png$$,
   $$Destiny is gids op Bonaire, een van de eilanden van Caribisch Nederland. Ze gaat met toeristen kajakken in Lac Cai.$$, 'inline'),
  ('00950524-89ae-4636-b40c-2529422dd635', 'f9444b72-3021-4f43-b449-593c3fe00314', $$kader: rode mangrove en zuurstofarme bodem (afbeelding 1 en 2)$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context2.png$$,
   $$Lac Cai (afbeelding 1) is een beschermd natuurgebied met zeegrasvelden en mangrovebos. Er groeit veel rode mangrove (Rhizophora mangle, afbeelding 2). Deze boomsoort heeft roodbruine wortels die uit de stam groeien.
De bomen staan in ondiep, zout water. Op de bodem bevindt zich een grote hoeveelheid afgevallen dode bladeren tussen de wortels. Dit bladafval leidt ertoe dat de bodem er zuurstofarm is.
afbeelding 1: kaart van Bonaire met de Caribische Zee, Kralendijk en Lac Cai
afbeelding 2: foto van een kajak tussen de mangrovebomen$$, 'inline'),
  ('6943c325-7006-4a3a-ad8b-308631af0c96', 'f9444b72-3021-4f43-b449-593c3fe00314', $$zwarte mangrove met ademwortels$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context3.png$$,
   $$Destiny laat zien dat de zwarte mangrove (Avicennia germinans) speciale ademwortels heeft die net boven het wateroppervlak uitsteken. Ze vertelt dat via gaatjes in deze ademwortels zuurstof wordt opgenomen en wordt getransporteerd naar de weefsels in de wortels. Daar wordt de zuurstof verbruikt.$$, 'inline'),
  ('989d555c-0b32-4181-b134-e895b18d27d5', 'f9444b72-3021-4f43-b449-593c3fe00314', $$zoutklieren in de bladeren van de zwarte mangrove$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context4.png$$,
   $$Destiny plukt bladeren van de zwarte mangrove en laat de toeristen eraan likken. Die bladeren smaken heel zout. Dit komt doordat de bladeren speciale klieren hebben om zout uit te scheiden. Hiermee reguleert de zwarte mangrove de osmotische waarde van de cellen van de bladeren.$$, 'inline'),
  ('c3eea99b-2351-4055-88e4-0002e68be950', 'f9444b72-3021-4f43-b449-593c3fe00314', $$kader: zeegrasvelden en Halophila stipulacea (afbeelding 3)$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context5.png$$,
   $$De zeegrasvelden (afbeelding 3) in Lac Cai bestaan grotendeels uit twee soorten zeegras: Thalassia testudinum en Syringodium filiforme. Sinds 2010 groeit ook de zeegrassoort Halophila stipulacea in Lac Cai. Deze soort is waarschijnlijk meegekomen met schepen vanuit de Rode zee.
afbeelding 3: onderwaterfoto van een zeegrasveld$$, 'inline'),
  ('793d5d6f-7976-4c0d-9739-838d13022e65', 'f9444b72-3021-4f43-b449-593c3fe00314', $$H. stipulacea verdringt T. testudinum; eutrofiëring$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context6.png$$,
   $$H. stipulacea kan het inheemse zeegras T. testudinum verdringen. Waarschijnlijk speelt eutrofiëring daarbij een belangrijke rol.$$, 'inline'),
  ('f3e8026d-a697-4a50-af95-774b4e8f7c17', 'f9444b72-3021-4f43-b449-593c3fe00314', $$kader: onderzoek naar diversiteit aan vissen (tabel 1)$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context7.png$$,
   $$Op Bonaire gaat de verdringing van T. testudinum door H. stipulacea veel langzamer dan op het buureiland Aruba. Onderzoekers vermoeden dat dit komt doordat in de zee rondom Bonaire de diversiteit aan vissen groter is dan op Aruba.
Sommige vissoorten eten van het zeegras, waardoor ze de groei van zeegras kunnen beperken.
Om de diversiteit te bepalen, plaatsten de onderzoekers een groot aantal onderwatercamera’s in gebieden bij Bonaire en Aruba. Vervolgens telden ze het aantal vissen en het aantal vissoorten. De resultaten staan in tabel 1.
tabel 1: totaal aantal vissen / aantal vissoorten
bij Bonaire: 566 / 28
bij Aruba: 472 / 14$$, 'inline'),
  ('2c07088f-2c70-4c89-87e7-61cb95b01b54', 'f9444b72-3021-4f43-b449-593c3fe00314', $$vergelijkbare abiotische factoren in de onderzoeksgebieden$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context8.png$$,
   $$Om de resultaten op Bonaire en Aruba te kunnen vergelijken, selecteerden de onderzoekers gebieden waar de abiotische factoren zoveel mogelijk overeenkomen.$$, 'inline'),
  ('3cca5d2e-2ec1-4bd0-913b-9d2ea896830e', 'f9444b72-3021-4f43-b449-593c3fe00314', $$drie uitspraken over het onderzoek$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context9.png$$,
   $$Hieronder staan uitspraken over het onderzoek.
1 De diversiteit aan vissen is groter op Bonaire dan op Aruba.
2 Een grotere diversiteit aan vissen gaat de verdringing van T. testudinum door H. stipulacea tegen.
3 Doordat vissen eten van H. stipulacea, wordt de verdringing van T. testudinum verhinderd.$$, 'inline'),
  ('4bd44247-26e8-47d7-ac66-8b0b66c4dca6', 'f9444b72-3021-4f43-b449-593c3fe00314', $$vliegreizen en het versterkt broeikaseffect$$,
   $$biologie-havo-2026-ii-bon-bin-na-boneiru-welkom-op-bonaire-context10.png$$,
   $$De toeristen hebben genoten van de prachtige natuur van Lac Cai. Een van hen voelt zich ook een beetje schuldig, omdat bij vliegreizen veel broeikasgassen vrijkomen. Het versterkt broeikaseffect kan leiden tot aantasting van de natuurgebieden van Bonaire.$$, 'inline'),
  ('01affe5a-f790-41ef-b1cf-bd9a4ae46556', '9ad77ccc-6785-40d7-b521-f42ec1ec13d8', $$inleiding: Sophie doet onderzoek naar orka’s$$,
   $$biologie-havo-2026-ii-omas-aan-de-top-context1.png$$,
   $$Sophie studeert Kust- en Zee-management. Voor haar stage mariene biologie neemt ze deel aan onderzoek naar orka’s.$$, 'inline'),
  ('ce54b4c0-f205-4145-a044-97dd07b35c44', '9ad77ccc-6785-40d7-b521-f42ec1ec13d8', $$kader: voedselrelaties van orka’s (foto)$$,
   $$biologie-havo-2026-ii-omas-aan-de-top-context2.png$$,
   $$Orka’s (Orcinus orca) zijn zeezoogdieren die behoren tot de tandwalvissen. Ze leven in familiegroepen.
Orka’s eten voornamelijk vissen. Ook eten ze inktvissen, zeehonden, kleine walvissoorten en zeevogels. Vissen, inktvissen en kleine walvissoorten voeden zich met zoöplankton. Zeevogels leven van vis. Inktvissen, vissen en zeevogels worden gegeten door zeehonden. Algen zijn het voedsel voor zoöplankton.
foto: twee springende orka’s$$, 'inline'),
  ('99645cc7-7274-4451-86a5-337ba7532d49', '9ad77ccc-6785-40d7-b521-f42ec1ec13d8', $$in het informatiekader is een voedselweb beschreven$$,
   $$biologie-havo-2026-ii-omas-aan-de-top-context3.png$$,
   $$In de tekst in het bovenstaande informatiekader is een voedselweb beschreven.$$, 'inline'),
  ('1c0e7e23-7163-45cb-8156-c5356e0f7e25', '9ad77ccc-6785-40d7-b521-f42ec1ec13d8', $$de orka is onderdeel van het voedselweb$$,
   $$biologie-havo-2026-ii-omas-aan-de-top-context4.png$$,
   $$De orka is onderdeel van het voedselweb in het informatiekader.$$, 'inline'),
  ('e7f6f72f-49e4-47f3-9bad-3cdfe1f33f52', '9ad77ccc-6785-40d7-b521-f42ec1ec13d8', $$kader: menopauze bij orka’s (oma’s)$$,
   $$biologie-havo-2026-ii-omas-aan-de-top-context5.png$$,
   $$Bij de meeste diersoorten blijven de vrouwtjes hun hele leven vruchtbaar. Bij de orka en enkele andere tandwalvissoorten hebben de vrouwtjes een menopauze, net als bij de mens. Na de menopauze zijn orkavrouwtjes niet meer vruchtbaar. Deze orka’s worden oma’s genoemd.$$, 'inline'),
  ('3676089d-e115-4f0e-8f10-ac948801c538', '9ad77ccc-6785-40d7-b521-f42ec1ec13d8', $$evolutionaire stamboom van tandwalvissen en drie uitspraken$$,
   $$biologie-havo-2026-ii-omas-aan-de-top-context6.png$$,
   $$Hieronder staat de evolutionaire stamboom van tandwalvissen. Deze stamboom is gemaakt op basis van DNA-onderzoek.
stamboom: ((orka, ((griend, Indische griend), witlipdolfijn)), (bruinvis, (narwal, beluga)))
heeft menopauze: orka, Indische griend, narwal, beluga; heeft geen menopauze: griend, witlipdolfijn, bruinvis
Hieronder staan uitspraken over de stamboom van tandwalvissen.
1 Uit de stamboom blijkt dat de voorouder van alle tandwalvissen een menopauze had.
2 De witlipdolfijn is nauwer verwant aan de orka dan aan de bruinvis.
3 Het DNA van de beluga komt het meest overeen met het DNA van de narwal.$$, 'inline'),
  ('584f4482-e1ba-43b3-a010-6e524c0bcd13', '9ad77ccc-6785-40d7-b521-f42ec1ec13d8', $$zwempositie van de oma’s en de hoeveelheid zalm (afbeelding)$$,
   $$biologie-havo-2026-ii-omas-aan-de-top-context7.png$$,
   $$Sophie loopt stage bij wetenschappers die de rol van de oma’s in de familiegroepen onderzoeken.
De oma’s hebben veel kennis over het leefgebied. Sophie heeft tijdens haar stage de oma’s binnen één groep orka’s bestudeerd. Zij zag dat de zwempositie van de oma’s samenhangt met de hoeveelheid zalm in de zee. De resultaten van haar observaties zijn in de afbeelding schematisch weergegeven.
afbeelding (kolommen volgers / leiders / zalmen; legenda: mannetje, jong vrouwtje, oma):
bovenste situatie, veel zalmen: volgers 2 oma’s, 1 jong vrouwtje en 1 mannetje; leiders 1 oma, 1 jong vrouwtje en 2 mannetjes
onderste situatie, weinig zalmen: volgers 1 oma, 1 jong vrouwtje en 2 mannetjes; leiders 2 oma’s, 1 jong vrouwtje en 1 mannetje
De wetenschappers denken dat de populatie orka’s een betere overlevingskans heeft door de kennis en het gedrag van de oma’s.$$, 'inline'),
  ('4308f1c7-9776-41ea-b09c-6b18ca205e9e', '0449c44c-8938-49f2-a7e3-542602ec1596', $$inleiding: Michael wil vegan gaan eten$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context1.png$$,
   $$Michael wil veganistisch (vegan) gaan eten, omdat dat beter is voor het milieu. Hij wil wel voldoende eiwitten binnenkrijgen.$$, 'inline'),
  ('9ea6e1d8-4772-4fb4-941e-1b7d00645d2c', '0449c44c-8938-49f2-a7e3-542602ec1596', $$kader: eiwitten, mineralen en vitamines bij veganistisch eten$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context2.png$$,
   $$Als je veganistisch eet, eet je geen dierlijke producten. Vlees, vis en zuivel zijn echter een belangrijke bron van eiwitten. Veganisten moeten daarom plantaardige voedingsmiddelen eten met voldoende eiwitten. Ook moeten zij er extra op letten dat ze genoeg mineralen en vitamines binnenkrijgen.
afbeelding: logo ‘vegan product’$$, 'inline'),
  ('56af5063-5510-49bd-904f-40824f8509ce', '0449c44c-8938-49f2-a7e3-542602ec1596', $$eiwitafbraak; delen van het spijsverteringsstelsel$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context3.png$$,
   $$In het spijsverteringskanaal worden eiwitten afgebroken tot aminozuren. Hieronder staan delen van het spijsverteringsstelsel.
− mondholte
− maag
− twaalfvingerige darm
− dunne darm
− dikke darm$$, 'inline'),
  ('b2867b15-6009-4baa-8cac-58fd08f609d3', '0449c44c-8938-49f2-a7e3-542602ec1596', $$drie uitspraken over aminozuren$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context4.png$$,
   $$Hieronder staan uitspraken over aminozuren.
1 Aerobe dissimilatie van aminozuren levert energie op.
2 De hoeveelheid aminozuren in het bloed wordt geregeld door de hormonen glucagon en insuline.
3 Een teveel aan aminozuren wordt in het lichaam als eiwitreserve opgeslagen.$$, 'inline'),
  ('73abb7e2-a295-4ef7-88f6-3f540b0a14ce', '0449c44c-8938-49f2-a7e3-542602ec1596', $$essentiële aminozuren voor de opbouw van eiwitten$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context5.png$$,
   $$Michael gaat op zoek naar plantaardige producten die de essentiële aminozuren bevatten die hij nodig heeft voor de opbouw van eiwitten in zijn lichaam.$$, 'inline'),
  ('a90366b4-d6cf-48ac-8903-e4e70f9e4059', '0449c44c-8938-49f2-a7e3-542602ec1596', $$tabel: eiwitten en aminozuren in witte bonen en rundvlees; drie uitspraken$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context6.png$$,
   $$In dierlijke eiwitproducten zijn essentiële aminozuren meestal in een goede verhouding aanwezig. Voor plantaardige producten geldt dat niet. Door verschillende plantaardige producten te combineren, kan je toch de essentiële aminozuren in een goede verhouding binnenkrijgen.
Michael vindt op internet een tabel met informatie over eiwitten en de meest voorkomende aminozuren in witte bonen en rundvlees.
tabel: witte bonen / rundvlees
eiwit in g per 100 g: 9,73 / 26,29
percentage energie afkomstig uit eiwit: 28 / 61
percentage van de aanwezige aminozuren:
asparagine + asparaginezuur: 12,7 / 9,4
glutamine + glutaminezuur: 16,0 / 15,1
leucine: 8,0 / 7,8
lysine: 6,9 / 8,3
Hieronder staan uitspraken over de tabel.
1 Van de aanwezige aminozuren is in witte bonen het percentage essentiële aminozuren hoger dan in rundvlees.
2 100 gram witte bonen bevat meer leucine dan 100 gram rundvlees.
3 Het grootste deel van de energie in rundvlees wordt geleverd door eiwitten.$$, 'inline'),
  ('44ea9405-288a-4401-a050-13850ac4782d', '0449c44c-8938-49f2-a7e3-542602ec1596', $$ijzertekort en hemoglobine$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context7.png$$,
   $$Michael moet erop letten dat hij voldoende ijzer binnenkrijgt. IJzer dat in groenten aanwezig is, wordt namelijk niet altijd goed door het lichaam opgenomen. Hierdoor kan er een tekort aan hemoglobine ontstaan. Dit kan leiden tot klachten zoals vermoeidheid en duizeligheid.$$, 'inline'),
  ('80e0c3c8-5858-43c1-a441-1213de0a07ab', '0449c44c-8938-49f2-a7e3-542602ec1596', $$kalium, natrium en bloeddruk in de nieren$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context8.png$$,
   $$Michael leest op een forum dat vegan eten beter is voor je nieren. Een vegan dieet bevat vaak meer kalium en minder natrium. Dit heeft een bloeddrukverlagend effect. Een hoge bloeddruk is een van de oorzaken van nierproblemen.$$, 'inline'),
  ('565d9fd5-27a4-492b-b7cc-e53312770942', '0449c44c-8938-49f2-a7e3-542602ec1596', $$kader: vitamine B12 uit mutante bacteriën$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context9.png$$,
   $$Veganisten kunnen ook een tekort krijgen aan vitamine B12. De meeste veganisten gebruiken voedingssupplementen met vitamine B12. Michael wil weten of die voedingssupplementen wel echt veganistisch zijn.
Op internet leest hij:
Vitamine B12 in supplementen wordt gemaakt door bacteriën in een laboratorium. Hiervoor worden vaak bacteriestammen gebruikt waarin genetische veranderingen zijn opgewekt door blootstelling aan straling of chemicaliën. Soms ontstaat daardoor bij één bacterie toevallig een kleine genetische verandering in een gen waardoor die bacterie meer B12 gaat produceren. Na selectie wordt deze mutante bacterie vermenigvuldigd tot grote aantallen.$$, 'inline'),
  ('e2fc6c52-444f-4bc9-9760-a89043b91818', '0449c44c-8938-49f2-a7e3-542602ec1596', $$stelling: minder landbouwgrond bij veganistisch eten$$,
   $$biologie-havo-2026-ii-kiezen-voor-vegan-context10.png$$,
   $$Michael vertelt aan zijn ouders wat het milieuvoordeel is van veganistisch eten. Hij stelt:
Als iedereen veganistisch zou eten, zou er veel minder landbouwgrond nodig zijn.$$, 'inline'),
  ('b1ac54de-0301-4740-b60e-717ada2ff794', 'ca5babac-d971-42cd-b577-fc6d7e187287', $$inleiding: profielwerkstuk over bloedgroepen$$,
   $$biologie-havo-2026-ii-de-vel-bloedgroep-context1.png$$,
   $$Isa, Kate en Mounir werken aan een profielwerkstuk over bloedgroepen. Behalve de resusfactor en de bloedgroep uit het AB0-systeem, wordt tegenwoordig bij een bloedtransfusie ook de Vel-bloedgroep gecontroleerd.$$, 'inline'),
  ('43a7b13c-9f72-408f-b20b-46ba488d03dc', 'ca5babac-d971-42cd-b577-fc6d7e187287', $$kader: Vel-negatieve personen$$,
   $$biologie-havo-2026-ii-de-vel-bloedgroep-context2.png$$,
   $$Een op de vijfduizend mensen heeft geen Vel-eiwit op het celmembraan van de rode bloedcellen. Deze personen zijn Vel-negatief. Na transfusie met Vel-positief bloed kan bij hen een levensgevaarlijke klontering ontstaan.$$, 'inline'),
  ('2d030bbd-efac-4f69-9da7-b9a2ab3813ce', 'ca5babac-d971-42cd-b577-fc6d7e187287', $$ontdekking van het Vel-eiwit; uitspraken van Isa, Kate en Mounir$$,
   $$biologie-havo-2026-ii-de-vel-bloedgroep-context3.png$$,
   $$Het Vel-eiwit werd in 1952 ontdekt toen bloedklontering werd waargenomen na een tweede bloedtransfusie bij een patiënt: mevrouw Vel. Ze had rode bloedcellen ontvangen van een donor met dezelfde AB0-bloedgroep en dezelfde resusbloedgroep.
Isa, Kate en Mounir doen elk een uitspraak over deze tweede bloedtransfusie. Ga ervan uit dat bij de transfusies alleen rode bloedcellen gedoneerd werden.
Isa: De gedoneerde rode bloedcellen bevatten Vel-antigenen.
Kate: De rode bloedcellen van mevrouw Vel bevatten antistoffen tegen de Vel-eiwitten.
Mounir: Door de eerste transfusie zijn B-cellen geactiveerd bij mevrouw Vel.$$, 'inline'),
  ('1b943314-a805-465f-b76a-3e444358ea10', 'ca5babac-d971-42cd-b577-fc6d7e187287', $$kader: het SMIM1-gen en een allel van 220 nucleotiden$$,
   $$biologie-havo-2026-ii-de-vel-bloedgroep-context4.png$$,
   $$Het gen dat codeert voor het Vel-eiwit is het SMIM1-gen. Dit gen bestaat uit 237 nucleotiden. Er is ook een variant van het SMIM1-gen die uit 220 nucleotiden bestaat. Dit allel is ontstaan door een mutatie en codeert niet voor een Vel-eiwit.$$, 'inline'),
  ('74599098-b969-41ea-bf30-200bfba11dc2', 'ca5babac-d971-42cd-b577-fc6d7e187287', $$processen bij de expressie van het SMIM1-gen$$,
   $$biologie-havo-2026-ii-de-vel-bloedgroep-context5.png$$,
   $$Normaal komt het SMIM1-gen tot expressie bij de vorming van rode bloedcellen uit bloedstamcellen. Hieronder staan processen die daarbij plaatsvinden.
1 het aflezen van het DNA
2 het inbouwen van het eiwit in de celmembraan
3 het transport van het mRNA uit de kern
4 het vormen van de keten van aminozuren aan een ribosoom
5 het vouwen van de polypeptideketen$$, 'inline'),
  ('627cb286-726a-472f-8f09-a08fd73bdc38', 'ca5babac-d971-42cd-b577-fc6d7e187287', $$gel-elektroforese van het SMIM1-gen van Isa, Kate en Mounir$$,
   $$biologie-havo-2026-ii-de-vel-bloedgroep-context6.png$$,
   $$Bloedbanken zijn altijd op zoek naar bloeddonoren met Vel-negatief bloed, omdat er daar maar weinig van zijn. Isa, Kate en Mounir gaan naar de bloedbank om te kijken of zij zo’n bloeddonor kunnen worden. Bij ieder wordt een buisje bloed afgenomen.
In het laboratorium wordt DNA geïsoleerd uit het bloed. Het SMIM1-gen wordt uit het DNA geknipt. Het DNA-fragment met dit gen wordt vermeerderd.
De DNA-fragmenten worden met gel-elektroforese gescheiden op basis van lengte. Hierbij gaan kleinere fragmenten sneller door de gel dan grotere fragmenten. In de afbeelding staan de resultaten van de gel-elektroforese van de DNA-fragmenten van Isa, Kate en Mounir.
afbeelding: gel met banden bij lengte 237 en 220 (verplaatsingsrichting naar beneden)
controle: 237 en 220
Isa: alleen 237
Kate: alleen 220
Mounir: 237 en 220$$, 'inline'),
  ('56bc57cb-5a21-45b2-ab4c-09d76b501ebd', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$inleiding: kleuren en vachtpatronen bij katten$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context1.png$$,
   $$Voor kattenfokker Benno is het belangrijk om te weten hoe de verschillende kleuren en vachtpatronen bij katten erfelijk bepaald zijn.$$, 'inline'),
  ('4521c592-c4a4-4d72-a46c-2a86d922623d', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$kader: albino-katten en tyrosinase (afbeelding 1 en 2, reactie 1)$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context2.png$$,
   $$Benno fokt albino-katten, die een witte vacht hebben (afbeelding 1). Deze katten hebben een mutatie in het gen voor tyrosinase. Dit gen ligt niet op een geslachtschromosoom. Donkergekleurde katten behoren tot het wildtype (afbeelding 2). Tyrosinase is nodig voor de vorming van het pigment melanine.
afbeelding 1: foto van een witte albino-kat
afbeelding 2: foto van een donkergekleurde kat (wildtype)
Tyrosinase zet de stof tyrosine om in de stof dopaquinine (reactie 1).
reactie 1: tyrosine → (tyrosinase) → dopaquinine
Uit dopaquinine wordt daarna via een aantal vervolgreacties melanine gevormd.$$, 'inline'),
  ('3e81099d-6798-4168-802f-dbf7bac5b299', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$kader: tabel met nucleotide- en aminozuurvolgorde van tyrosinase$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context3.png$$,
   $$In het tyrosinase-gen van albino-katten ontbreekt op één plaats een nucleotide. Hierdoor kan er geen werkzame tyrosinase ontstaan.
In de tabel zie je een gedeelte van de genetische code voor tyrosinase met de bijbehorende aminozuurvolgorde.
nucleotidevolgorde (posities 1 t/m 13):
wildtype: AGG CUC CCC UCC UCU GCU GAU GUG GAA UUU UGC CUA AGU
albino: AGG CUC CCU CCU CUG CUG AUG UGG AAU UUU GCC UAA GUC
aminozuurvolgorde (posities 1 t/m 13):
wildtype: R L P S S A D V E F C L S
albino: R L P P W W M W N F A (posities 12 en 13 leeg)$$, 'inline'),
  ('acb31f63-dec5-4892-89b8-f34fdf903f1a', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$tyrosinase bij albino-katten is korter$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context4.png$$,
   $$Tyrosinase bij albino-katten is korter dan bij wildtype-katten.$$, 'inline'),
  ('bec7124f-48a0-4ad3-acd8-c8113a061ad3', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$allel T is dominant over allel t$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context5.png$$,
   $$Een kat met een niet-gemuteerd tyrosinase-allel (T) en een gemuteerd tyrosinase-allel (t) is donkergekleurd. Hieruit blijkt dat het niet-gemuteerde allel dominant is over het gemuteerde allel.$$, 'inline'),
  ('11686f99-239a-4841-b3b5-8276d89cdf6e', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$kader: allelen tˢ en tᵇ en temperatuurgevoelige tyrosinase$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context6.png$$,
   $$Er zijn bij katten ook nog twee andere mutaties van het tyrosinase-gen bekend: tˢ en tᵇ. Deze allelen zijn recessief ten opzichte van het wildtype allel T. De allelen tᵇ en tˢ coderen voor tyrosinase-enzymen die bij de lichaamstemperatuur van katten (38,5 °C) minder goed werken. Bij een lagere temperatuur werken die enzymen wel. De snuit, oren, poten en staart van katten met deze allelen zijn hierdoor donkerder van kleur.$$, 'inline'),
  ('1dc04871-155b-421d-84e2-872dbb30fd2d', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$kader: kleuringen met genotype (afbeelding 3)$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context7.png$$,
   $$Verschillende combinaties van allelen van het tyrosinase-gen kunnen leiden tot verschillende kleuringen. In afbeelding 3 staan verschillende kleuringen aangegeven met het bijbehorende genotype.
afbeelding 3: Siamese kleuring tˢtˢ (lichte romp, donkere snuit, oren, poten en staart); minkkleuring tˢtᵇ (middelgrijze romp); Burmese kleuring tᵇtᵇ (donkergrijze romp); bij alle drie zijn snuit, oren, poten en staart donker$$, 'inline'),
  ('72c4b72e-8ff4-406f-86f5-b3811c8e3e69', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$drie uitspraken over de kleuringen$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context8.png$$,
   $$Hieronder staan uitspraken over de kleuringen.
1 De minkkleuring is een intermediair fenotype.
2 Tyrosinase gecodeerd door tˢ is beter bestand tegen hoge temperaturen dan tyrosinase gecodeerd door tᵇ.
3 Bij een kat met Siamese kleuring hebben de huidcellen in de staart een ander genotype dan de huidcellen op de buik.$$, 'inline'),
  ('c5ead05d-5c2d-4a54-b57d-9b3a0596dbbe', 'c88db3da-d5d8-4be5-8874-f9acdb904ee4', $$kruising met de grootste kans op mink-gekleurde nakomelingen$$,
   $$biologie-havo-2026-ii-katten-bekennen-kleur-context9.png$$,
   $$Mink-gekleurde katten zijn tegenwoordig erg populair. Benno wil daarom een kruising uitvoeren waarbij de kans op mink-gekleurde nakomelingen het grootst is.$$, 'inline'),
  ('1363358d-0bd6-46f3-a499-e108b0b4d9b6', 'd5c45293-5238-4f66-8fa0-6a98fd19a548', $$inleiding en kader: vertering van cellulose en zetmeel bij paarden; drie uitspraken$$,
   $$biologie-havo-2026-ii-paarden-voeren-zonder-brokken-context1.png$$,
   $$Koen heeft een paardenboerderij. In de wintermaanden voert hij de paarden bij met brokken krachtvoer. Hij onderzoekt of het mogelijk is om de paarden het hele jaar te voeren met gras en hooi (gedroogd gras) van zijn eigen graslanden, omdat dit duurzamer en goedkoper is.
foto: paard in een stal met hooi
Hooi bevat cellulose en zetmeel. De vertering en opname van deze koolhydraten verlopen bij paarden net als bij mensen. Net als mensen hebben paarden geen eigen enzymen voor de vertering van cellulose. Maar veel van de cellulose wordt verteerd door bacteriën in de blinde darm en dikke darm. De verteringsproducten worden opgenomen door de darmwand.
Hieronder staan uitspraken over vertering en opname van koolhydraten.
1 In de maag is de pH optimaal voor de werking van amylase.
2 In de dunne darm worden monosachariden opgenomen in het bloed.
3 Bij de afbraak van cellulose door bacteriën ontstaan organische stoffen.$$, 'inline'),
  ('ab9b45f8-fa3e-4432-a422-21133c6a9b9b', 'd5c45293-5238-4f66-8fa0-6a98fd19a548', $$kader: fructaan in gras en hooi$$,
   $$biologie-havo-2026-ii-paarden-voeren-zonder-brokken-context2.png$$,
   $$Gras en hooi voor paarden mogen niet te veel fructaan bevatten. Fructaan is een koolhydraat dat is opgebouwd uit de monosachariden fructose en glucose. Wanneer paarden gras met veel fructaan eten, kunnen ze darmproblemen krijgen. Een gedeelte van de monosachariden die overdag worden geproduceerd bij fotosynthese, wordt opgeslagen als fructaan. Als fructaan wordt omgezet, kunnen de producten worden gebruikt voor de groei van het gras. Een hoog fructaangehalte in gras kan ontstaan als de temperatuur ’s nachts lager is dan 5 °C. In het gras wordt fructaan dan nauwelijks omgezet.$$, 'inline'),
  ('72622ce7-9a8a-4754-acf2-b643b545b7b4', 'd5c45293-5238-4f66-8fa0-6a98fd19a548', $$bacteriële omzetting van fructaan in de dikke darm$$,
   $$biologie-havo-2026-ii-paarden-voeren-zonder-brokken-context3.png$$,
   $$Een paard maakt geen enzymen aan voor de vertering van fructaan. De fructaanmoleculen kunnen wel worden omgezet tot monosachariden door bacteriën in de dikke darm. Hierbij komen gassen vrij die zich ophopen en daardoor darmproblemen veroorzaken.$$, 'inline'),
  ('8437bb1b-200d-4d90-a135-14bcb5fe8c2c', 'd5c45293-5238-4f66-8fa0-6a98fd19a548', $$diarree door vorming van monosachariden$$,
   $$biologie-havo-2026-ii-paarden-voeren-zonder-brokken-context4.png$$,
   $$Door de vorming van monosachariden in de dikke darm kan een paard ook last krijgen van diarree (waterige ontlasting).$$, 'inline'),
  ('fcb6df6d-371b-4166-b9c6-f5c14a550766', 'd5c45293-5238-4f66-8fa0-6a98fd19a548', $$kader: diagram fructaangehalte van koeien- en paardengrassen$$,
   $$biologie-havo-2026-ii-paarden-voeren-zonder-brokken-context5.png$$,
   $$Koen wil weten welke grassoorten hij het best kan inzaaien. Op de website van een graszadenleverancier leest hij dat grassoorten worden ingedeeld in koeiengrassen en paardengrassen.
In het diagram zie je dat het fructaangehalte van grassen afhankelijk is van de grassoort en van het seizoen. Op basis van het fructaangehalte worden grassoorten ingedeeld als koeiengras of paardengras.
In het diagram is één grassoort aangegeven met de letter Q.
diagram: fructaangehalte voorjaar (%) op de x-as, fructaangehalte zomer (%) op de y-as
paardengrassen (ongeveer): (1,8; 2,4), (2,1; 2,2), (2,8; 3,8), (3,0; 3,0), (3,2; 3,5)
koeiengrassen (ongeveer): (3,5; 5,2), (3,9; 5,9), (4,0; 5,0), (4,1; 4,9), (4,3; 5,8), (5,0; 6,0), (5,9; 6,2), (6,0; 6,0), (6,5; 6,0)
de letter Q staat bij het meest rechtse koeiengras (ongeveer 6,5% in het voorjaar en 6,0% in de zomer)$$, 'inline'),
  ('2f31d388-350a-44e3-9e29-408fc906011b', 'd5c45293-5238-4f66-8fa0-6a98fd19a548', $$drie uitspraken over het diagram$$,
   $$biologie-havo-2026-ii-paarden-voeren-zonder-brokken-context6.png$$,
   $$Hieronder staan uitspraken over de gegevens in het diagram.
1 De grassoort die in het voorjaar het hoogste fructaangehalte heeft, heeft ook in de zomer het hoogste fructaangehalte.
2 Paardengrassen bevatten zowel in het voorjaar als in de zomer gemiddeld minder fructaan dan koeiengrassen.
3 Gedurende het groeiseizoen neemt het fructaangehalte van soort Q toe.$$, 'inline'),
  ('33ef3da8-98a7-4c7d-93a8-15a0ffac3f22', 'd5c45293-5238-4f66-8fa0-6a98fd19a548', $$tabel: grassen in het mengsel met Latijnse namen$$,
   $$biologie-havo-2026-ii-paarden-voeren-zonder-brokken-context7.png$$,
   $$Koen kiest een mengsel van de volgende grassen:
Nederlandse naam / Latijnse naam
Engels raaigras / Lolium perenne
rood zwenkgras / Festuca rubra
straatgras / Poa annua
timotheegras / Phleum pratense
veldbeemdgras / Poa pratensis$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('09d915f3-b1a1-49b2-a263-51d331da3705', 'aea52887-ba8e-42f3-ab63-712a17759d93', 1,
   '[{"domain": "Zelfregulatie", "subdomain": "Afweer van het organisme"}]'::jsonb,
   '["aangeboren afweer", "fysische barrière", "chemische barrière", "trilhaarepitheel", "lysozym", "slijmvlies"]'::jsonb,
   $$Kiezen van de fysische en (bio)chemische barrière van de aangeboren afweer in de neusholte.$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-vraag1.png$$, $$2p 1 Welke fysische barrière is dit? En welke (bio)chemische barrière? Gebruik je informatieboek.
fysische barrière (bio)chemische barrière
A hoornlaag lage pH
B hoornlaag lysozymen
C trilhaarepitheel lage pH
D trilhaarepitheel lysozymen$$, array['1d56b8be-95f9-4875-8bc0-14d3480d6311', '22ccc262-f606-4708-b599-c935c94865d7', '4987535c-db77-4dc7-9735-ba2bed8617e9']::uuid[]),
  ('fbdc4b67-9532-4910-80b9-dd5dabddc851', 'aea52887-ba8e-42f3-ab63-712a17759d93', 2,
   '[{"domain": "Interactie", "subdomain": "Interactie in ecosystemen"}]'::jsonb,
   '["symbiose", "commensalisme", "parasitisme", "mutualisme", "voedselrelaties"]'::jsonb,
   $$Benoemen van de vorm van symbiose tussen mens en bacterie in het neusslijmvlies en in het inwendig milieu.$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-vraag2.png$$, $$2p 2 Welke vorm van symbiose is het meest passend bij de symbiose die optreedt in het neusslijmvlies? En welke bij die in het inwendig milieu?
neusslijmvlies inwendig milieu
A commensalisme mutualisme
B commensalisme parasitisme
C mutualisme commensalisme
D mutualisme parasitisme
E parasitisme commensalisme
F parasitisme mutualisme$$, array['22ccc262-f606-4708-b599-c935c94865d7', 'c6f929d4-9764-4b66-af06-830d1bceb9f6']::uuid[]),
  ('877e3f92-6c75-4c73-bbbc-c44e6e2cbde5', 'aea52887-ba8e-42f3-ab63-712a17759d93', 3,
   '[{"domain": "Zelfregulatie", "subdomain": "Afweer van het organisme"}]'::jsonb,
   '["virusinfectie", "dekweefselcellen", "eerste verdedigingslinie", "binnendringen ziekteverwekker"]'::jsonb,
   $$Verklaren dat een virus dekweefselcellen van de luchtwegen beschadigt, waardoor bacteriën makkelijker binnendringen.$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-vraag3.png$$, $$1p 3 Verklaar op celniveau waardoor zo’n virusinfectie de kans op binnendringen van de pneumokokbacterie vergroot.$$, array['22ccc262-f606-4708-b599-c935c94865d7', '6bf90a3e-943c-44da-b972-093e313a4a2d']::uuid[]),
  ('7d862047-99f3-47ef-bf75-86f7a62d5d22', 'aea52887-ba8e-42f3-ab63-712a17759d93', 4,
   '[{"domain": "Zelfregulatie", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["diffusie", "gaswisseling", "longblaasjes", "diffusieafstand", "formule interpreteren"]'::jsonb,
   $$Afleiden met een diffusieformule dat vocht in de longblaasjes de diffusieafstand vergroot en de diffusiesnelheid verkleint.$$,
   $$biologie-havo-2026-ii-schrik-voor-een-prik-vraag4.png$$, $$2p 4 Welke factor wordt groter door de slijmvorming? En hoe verandert dat de diffusiesnelheid?
factor die groter wordt / diffusiesnelheid wordt
A A groter
B A kleiner
C (c₂ − c₁) groter
D (c₂ − c₁) kleiner
E x groter
F x kleiner$$, array['c07219c1-53cf-416b-b971-3a12aff49000']::uuid[]),
  ('2e866a52-e7d6-4bbd-8931-bc4272a2bf88', 'aea52887-ba8e-42f3-ab63-712a17759d93', 5,
   '[{"domain": "Zelfregulatie", "subdomain": "Zelfregulatie van het organisme"}]'::jsonb,
